import 'dart:typed_data';

import 'package:share_plus/share_plus.dart';
import 'package:url_launcher/url_launcher.dart';

/// Shares (or on web, downloads) generated bytes such as QR PNGs, posters and PDFs.
Future<void> shareBytes(Uint8List bytes, String filename, String mime, {String? text}) async {
  await SharePlus.instance.share(ShareParams(files: [XFile.fromData(bytes, mimeType: mime, name: filename)], fileNameOverrides: [filename], text: text));
}

Future<void> shareText(String text, {String? subject}) => SharePlus.instance.share(ShareParams(text: text, subject: subject));

Future<void> openExternal(String url) => launchUrl(Uri.parse(url), mode: LaunchMode.externalApplication);

Future<void> callPhone(String phone) => launchUrl(Uri(scheme: 'tel', path: phone.replaceAll(RegExp(r'[^\d+]'), '')));

/// Opens WhatsApp chat with a Pakistani number (03xx → 923xx).
Future<void> whatsapp(String phone, [String text = '']) {
  var d = phone.replaceAll(RegExp(r'\D'), '');
  if (d.startsWith('0')) d = '92${d.substring(1)}';
  return launchUrl(Uri.parse('https://wa.me/$d${text.isEmpty ? '' : '?text=${Uri.encodeComponent(text)}'}'), mode: LaunchMode.externalApplication);
}
